Commit:     Kai Engert <kaie@kuix.de>
CommitDate: Thu Apr 23 16:23:06 2026 +0000

    Bug 1843860 - When creating decrypted copy, avoid adding multipart/mixed layer when payload is multipart/signed. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D295585

diff --git a/mail/extensions/openpgp/content/modules/MimeTree.sys.mjs b/mail/extensions/openpgp/content/modules/MimeTree.sys.mjs
index 1dec44dcc0a..8acfe43cce5 100644
--- a/mail/extensions/openpgp/content/modules/MimeTree.sys.mjs
+++ b/mail/extensions/openpgp/content/modules/MimeTree.sys.mjs
@@ -579,6 +579,7 @@ export class MimeTreeDecrypter {
     );
     m.initialize(data.substr(0, bodyIndex));
     let ct = m.extractHeader("content-type", false) || "";
+    const outerCt = ct;
     const part = mimeTreePart.partNum;

     if (part.length > 0 && part.search(/[^01.]/) < 0) {
@@ -614,33 +615,43 @@ export class MimeTreeDecrypter {
       }
     }

-    let boundary = getBoundary(mimeTreePart);
-    if (!boundary) {
-      boundary = lazy.EnigmailMime.createBoundary();
-    }
+    if (/^multipart\/signed/i.test(outerCt)) {
+      mimeTreePart.headers.get("content-type").type = "multipart/signed";
+      mimeTreePart.headers._rawHeaders.set("content-type", [outerCt]);

-    // append relevant headers
-    mimeTreePart.headers.get("content-type").type = "multipart/mixed";
-    mimeTreePart.headers._rawHeaders.set("content-type", [
-      'multipart/mixed; boundary="' + boundary + '"',
-    ]);
-    mimeTreePart.subParts = [
-      {
-        body: data,
-        decryptedPgpMime: true,
-        partNum: mimeTreePart.partNum + ".1",
-        headers: {
-          _rawHeaders: new Map(),
-          get() {
-            return null;
-          },
-          has() {
-            return false;
+      // Use the raw body from data directly, preserving exact bytes
+      // for signature verification.
+      mimeTreePart.body = data.substring(bodyIndex);
+      mimeTreePart.subParts = [];
+    } else {
+      let boundary = getBoundary(mimeTreePart);
+      if (!boundary) {
+        boundary = lazy.EnigmailMime.createBoundary();
+      }
+
+      // append relevant headers
+      mimeTreePart.headers.get("content-type").type = "multipart/mixed";
+      mimeTreePart.headers._rawHeaders.set("content-type", [
+        'multipart/mixed; boundary="' + boundary + '"',
+      ]);
+      mimeTreePart.subParts = [
+        {
+          body: data,
+          decryptedPgpMime: true,
+          partNum: mimeTreePart.partNum + ".1",
+          headers: {
+            _rawHeaders: new Map(),
+            get() {
+              return null;
+            },
+            has() {
+              return false;
+            },
           },
+          subParts: [],
         },
-        subParts: [],
-      },
-    ];
+      ];
+    }

     this.cryptoChanged = true;
   }
diff --git a/mail/test/browser/openpgp/browser_perm_decrypt.js b/mail/test/browser/openpgp/browser_perm_decrypt.js
